async function execute(ctx) {
  const body = ctx.body || {};
  const seed = (ctx.nodes && ctx.nodes.seed) || {};
  const name = body.name || seed.name || 'onebase';
  const a = Number(body.a != null ? body.a : seed.a) || 0;
  const b = Number(body.b != null ? body.b : seed.b) || 0;
  return {
    result: {
      engine: 'javascript',
      sum: a + b,
      greeting: 'hello ' + name,
      sha256_of_name: crypto.sha256(String(name)),
      has_api_token: !!env.get('API_TOKEN'),
      server_ts_ms: time.now_ms(),
      echo_body: body
    }
  };
}
